DROP TABLE IF EXISTS solazeroth_v3_aventurier_paliers, solazeroth_v3_montures;
CREATE TABLE solazeroth_v3_aventurier_paliers (palier TINYINT UNSIGNED NOT NULL PRIMARY KEY, points INT UNSIGNED NOT NULL, genre TINYINT UNSIGNED NOT NULL, valeur INT UNSIGNED NOT NULL);
